extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi correttamente"):
		return

	var mesh_east := find_by_name(main, "MeshEast") as MeshInstance3D
	if not check("mesh_east_exists", mesh_east != null, "In BlockEast serve un figlio MeshInstance3D chiamato MeshEast"):
		return
	var box_east := mesh_east.mesh as BoxMesh
	if check("box_east_mesh", box_east != null, "MeshEast deve usare una BoxMesh"):
		check("box_east_size", box_east.size == Vector3(3, 2, 3), "La BoxMesh di MeshEast deve avere Size = Vector3(3, 2, 3) (trovato %s)" % str(box_east.size))

	var mat_wood := mesh_east.material_override as StandardMaterial3D
	if check("mat_east_wood", mat_wood != null, "MeshEast deve avere un materiale StandardMaterial3D"):
		check("wood_roughness", absf(mat_wood.roughness - 0.8) < 0.05, "Il blocco est deve usare il materiale Legno opaco con Roughness = 0.8")

	var crystal := find_by_name(main, "Crystal") as MeshInstance3D
	if not check("crystal_exists", crystal != null, "In BlockEastTop serve un figlio MeshInstance3D chiamato Crystal"):
		return
	var sphere := crystal.mesh as SphereMesh
	check("crystal_mesh", sphere != null, "Crystal deve usare una SphereMesh")

	var mat_crystal := crystal.material_override as StandardMaterial3D
	if check("mat_crystal_exists", mat_crystal != null, "Crystal deve avere uno StandardMaterial3D in Material Override"):
		check("emission_enabled", mat_crystal.emission_enabled == true, "Il cristallo luminoso deve avere Emission abilitato (Enabled = true)")
		check("crystal_roughness", absf(mat_crystal.roughness - 0.2) < 0.05, "Il cristallo luminoso deve avere Roughness = 0.2 (trovato %.2f)" % mat_crystal.roughness)
		check("crystal_metallic", absf(mat_crystal.metallic - 0.0) < 0.05, "Il cristallo luminoso deve avere Metallic = 0.0 (trovato %.2f)" % mat_crystal.metallic)

